/** The outcome of a save. */
export interface SaveProjectResponse {
  /** The `.nova` format version written. */
  format_version: number;
  /** Where it was written. */
  path: string;
  /** The project that was saved. */
  project_id: string;
  /** Unix milliseconds of the save, for 'last saved'. */
  saved_at_ms: number;
}

/** Slide the source window inside a clip, moving neither end in time. */
export interface SlipClipRequest {
  /** The clip to slip. */
  clip_id: string;
  /** How far to slide the source window; may be negative. */
  delta_frames: number;
  /** Drag id: consecutive slips sharing one collapse into a single undo. */
  gesture?: string;
  /** Discriminator: which command this is. It is also the name the journal records. */
  type?: "slip-clip";
}

/** Cut a clip in two at a frame. */
export interface SplitClipRequest {
  /** Where to cut, in timeline frames. */
  at_frame: number;
  /** The clip to cut. */
  clip_id: string;
  /** Id for the second half; the server generates one when empty. */
  new_clip_id?: string;
  /** Discriminator: which command this is. It is also the name the journal records. */
  type?: "split-clip";
}

/** "Export this project, there, like that. */
export interface StartExportRequest {
  /** Video codec: h264, hevc, av1, prores, vp9. */
  codec?: string;
  /** Container: mp4, mov, mkv, webm. */
  container?: string;
  /** Constant quality, 0-51, lower is better. Ignored for a codec without a constant-quality mode. */
  crf?: number;
  /** Last timeline frame, exclusive. Omitted means the end of the project, resolved when the job runs rather than when it was queued. */
  end_frame?: number | null;
  /** Refuse the export when an asset is offline. Off by default: most projects being exported have at least one drive that is not plugged in. */
  fail_on_missing?: boolean;
  /** Move the index to the front so streaming starts immediately. */
  faststart?: boolean;
  /** Output height; defaults to the project's. */
  height?: number | null;
  /** Where the file goes. Absolute: a job runs in a worker whose working directory is not the user's. */
  path: string;
  /** Encoder preset: a dialog-exposed speed/quality knob. */
  preset?: string;
  /** Job urgency: low, normal or high. */
  priority?: string;
  /** First timeline frame, inclusive. */
  start_frame?: number;
  /** Output width; defaults to the project's. */
  width?: number | null;
}

/** Who this session is, for the window title, the About box and bug reports. */
export interface SystemInfoResponse {
  /** Where this session writes its data (ADR-0014). */
  data_dir: string;
  /** Whether this is a packaged build rather than a source run. */
  frozen: boolean;
  /** The host the service is bound to; `127.0.0.1` for a session. */
  host: string;
  /** Python implementation: CPython, PyPy, ... */
  implementation: string;
  /** Process id of the service. */
  pid: number;
  /** Operating system, as `platform.platform()` reports it. */
  platform: string;
  /** The port this session chose at startup; `0` when unbound. */
  port: number;
  /** The newest `.nova` format version this build reads and writes. */
  project_format_version: number;
  /** Python version string of the running interpreter. */
  python: string;
  /** Nova Studio version. */
  version: string;
}

/** The project's frame rate, in the two forms a UI needs. */
export interface TimebaseSummary {
  /** Denominator, e.g. 1001. 1 for whole rates. */
  den: number;
  /** Frames per second, for display only. */
  fps: number;
  /** Numerator of the frame rate, e.g. 30000. */
  num: number;
}

/** The edit, its history, and how much of it is on disk. */
export interface TimelineResponse {
  /** Whether the edit differs from the file. */
  dirty: boolean;
  /** What undo and redo would do. */
  history: HistorySummary;
  /** Newest journalled sequence; 0 for none. */
  journal_sequence: number;
  /** Edits since the last checkpoint. */
  pending_commands: number;
  /** The project this timeline belongs to. */
  project_id: string;
  /** The edit as it stands. */
  timeline: TimelineSummary;
}

/** The edit: its rate, its tracks, and how long it is. */
export interface TimelineSummary {
  /** How many clips there are, in total. */
  clip_count: number;
  /** Length of the whole edit, in frames. */
  duration_frames: number;
  /** The project's frame rate. */
  timebase: TimebaseSummary;
  /** How many tracks there are. */
  track_count: number;
  /** Tracks in display order. */
  tracks: TrackSummary[];
}

/** What a track carries, which decides how it is composited and mixed. */
export type TrackKind = "video" | "audio" | "caption" | "overlay" | "adjustment";

/** One track, with the clips on it in timeline order. */
export interface TrackSummary {
  /** Clips on this track. */
  clip_count: number;
  /** Its clips, in timeline order. */
  clips: ClipSummary[];
  /** End of the last clip on it. */
  duration_frames: number;
  /** Whether it is left out of the output. */
  hidden: boolean;
  /** Display order, 0 at the top. */
  index: number;
  /** What this track carries. */
  kind: TrackKind;
  /** Whether edits are refused on it. */
  locked: boolean;
  /** Whether its audio is muted. */
  muted: boolean;
  /** What to call it; may be empty. */
  name: string;
  /** Stable id; the key track commands use. */
  track_id: string;
}

/** Move one end of a clip to a frame. */
export interface TrimClipRequest {
  /** The clip to trim. */
  clip_id: string;
  /** Which end moves. */
  edge?: TrimEdge;
  /** Drag id: consecutive trims sharing one collapse into a single undo. */
  gesture?: string;
  /** Where the chosen end should land. */
  to_frame: number;
  /** Discriminator: which command this is. It is also the name the journal records. */
  type?: "trim-clip";
}

/** Which end of a clip a trim moves. */
export type TrimEdge = "start" | "end";

/**
 * The outcome of Ctrl+Z.
 *
 * `undone` is false when there was nothing to undo, which is **not** an error:
 * a user pressing undo on a fresh timeline has made no mistake.
 */
export interface UndoResponse {
  /** The command that was undone, or empty. */
  command_id: string;
  /** Whether the edit differs from the file. */
  dirty: boolean;
  /** What undo and redo would do now. */
  history: HistorySummary;
  /** Newest journalled sequence; 0 for none. */
  journal_sequence: number;
  /** What was undone, e.g. `move-clip`; empty for nothing. */
  name: string;
  /** Edits since the last checkpoint. */
  pending_commands: number;
  /** The project that was edited. */
  project_id: string;
  /** Whether anything was undone. */
  undone: boolean;
}

/**
 * One field of a request that did not match the schema.
 *
 * Named rather than positional in the payload because the frontend maps these
 * onto form fields, and a string it has to parse is a string it will parse
 * differently in two places.
 */
export interface ValidationField {
  /** Dotted path of the offending field within the request. */
  field: string;
  /** Machine-readable error type, e.g. `greater_than_equal`. */
  kind: string;
  /** What is wrong with it, as pydantic reported it. */
  message: string;
}

/** One video stream, as the bin and the inspector show it. */
export interface VideoSummary {
  /** The codec, as the file reported it. */
  codec_name: string;
  /** Height as it should be shown. */
  display_height: number;
  /** Width as it should be shown: aspect ratio and rotation applied. */
  display_width: number;
  /** Stream length, from the frame count and the rate. */
  duration_seconds: number;
  /** Frames in the stream; 0 when the file does not say. */
  frame_count: number;
  /** Exact rate as `num/den`, e.g. `30000/1001`. */
  frame_rate: string;
  /** Whether the file declared its colour, or left it unspecified. */
  has_colour_metadata: boolean;
  /** Coded height in pixels. */
  height: number;
  /** Pixel format, e.g. `yuv420p`. */
  pixel_format: string;
  /** Degrees to rotate for display: 0, 90, 180 or 270. */
  rotation: number;
  /** Coded width in pixels. */
  width: number;
}

/** Every schema in the contract, by name — how an operation's
 *  `requestBody` and `response` strings become types. */
export interface Schemas {
  readonly AssetKind: AssetKind;
  readonly AssetRef: AssetRef;
  readonly AudioSummary: AudioSummary;
  readonly AuditResponse: AuditResponse;
  readonly CacheKind: CacheKind;
  readonly CapabilitiesResponse: CapabilitiesResponse;
  readonly CheckpointResponse: CheckpointResponse;
  readonly ClipKind: ClipKind;
  readonly ClipSpec: ClipSpec;
  readonly ClipSummary: ClipSummary;
  readonly CommandResponse: CommandResponse;
  readonly ComponentStatus: ComponentStatus;
  readonly CreateProjectRequest: CreateProjectRequest;
  readonly EnsureMediaRequest: EnsureMediaRequest;
  readonly EnsureMediaResponse: EnsureMediaResponse;
  readonly ExportSubmission: ExportSubmission;
  readonly HealthResponse: HealthResponse;
  readonly HistorySummary: HistorySummary;
  readonly ImportFailure: ImportFailure;
  readonly ImportRequest: ImportRequest;
  readonly ImportResponse: ImportResponse;
  readonly JobCancelResponse: JobCancelResponse;
  readonly JobListResponse: JobListResponse;
  readonly JobProgressView: JobProgressView;
  readonly JobRecordView: JobRecordView;
  readonly LiftClipRequest: LiftClipRequest;
  readonly MediaAssetSummary: MediaAssetSummary;
  readonly MediaCacheDroppedResponse: MediaCacheDroppedResponse;
  readonly MediaCacheEntrySummary: MediaCacheEntrySummary;
  readonly MediaCacheResponse: MediaCacheResponse;
  readonly MediaCacheTrimResponse: MediaCacheTrimResponse;
  readonly MediaJobSummary: MediaJobSummary;
  readonly MediaListResponse: MediaListResponse;
  readonly MoveClipRequest: MoveClipRequest;
  readonly OpenProjectRequest: OpenProjectRequest;
  readonly OpenProjectResponse: OpenProjectResponse;
  readonly PreviewCacheResponse: PreviewCacheResponse;
  readonly PreviewSourcesResponse: PreviewSourcesResponse;
  readonly PreviewWarmRequest: PreviewWarmRequest;
  readonly PreviewWarmResponse: PreviewWarmResponse;
  readonly ProblemResponse: ProblemResponse;
  readonly ProjectSummary: ProjectSummary;
  readonly RecoveryResponse: RecoveryResponse;
  readonly RedoResponse: RedoResponse;
  readonly ReplaceTrackClipsRequest: ReplaceTrackClipsRequest;
  readonly RippleDeleteRequest: RippleDeleteRequest;
  readonly SaveAsRequest: SaveAsRequest;
  readonly SaveProjectResponse: SaveProjectResponse;
  readonly SlipClipRequest: SlipClipRequest;
  readonly SplitClipRequest: SplitClipRequest;
  readonly StartExportRequest: StartExportRequest;
  readonly SystemInfoResponse: SystemInfoResponse;
  readonly TimebaseSummary: TimebaseSummary;
  readonly TimelineResponse: TimelineResponse;
  readonly TimelineSummary: TimelineSummary;
  readonly TrackKind: TrackKind;
  readonly TrackSummary: TrackSummary;
  readonly TrimClipRequest: TrimClipRequest;
  readonly TrimEdge: TrimEdge;
  readonly UndoResponse: UndoResponse;
  readonly ValidationField: ValidationField;
  readonly VideoSummary: VideoSummary;
}

/** What one endpoint needs, as data rather than as a function, so
 *  that transport stays a policy and the table stays reviewable. */
export interface OperationSpec {
  readonly method: "get" | "post" | "put" | "patch" | "delete";
  readonly path: string;
  readonly summary: string;
  readonly pathParams: readonly string[];
  readonly queryParams: readonly string[];
  readonly requestBody: keyof Schemas | null;
  readonly response: keyof Schemas | null;
  readonly success: number;
  readonly responseFormat: "json" | "blob";
}

